<?php $title='Edit meeting'; $active='meetings'; require_once __DIR__ . '/_layout.php'; $pdo=db(); $id=(int)($_GET['id']??0); $item=['title'=>'','slug'=>'','starts_at'=>'','ends_at'=>'','location_name'=>'','location_details'=>'','featured_snack'=>'','focus_topic'=>'','presenter_name'=>'','presenter_topic'=>'','special_note'=>'','status'=>'draft']; if($id){$st=$pdo->prepare('SELECT * FROM meetings WHERE id=?');$st->execute([$id]);$item=$st->fetch() ?: $item;} if($_SERVER['REQUEST_METHOD']==='POST'){ $slug=$_POST['slug'] ?: slugify($_POST['title']); $values=[$_POST['title'],$slug,$_POST['starts_at'],($_POST['ends_at'] ?: null),($_POST['location_name'] ?: null),($_POST['location_details'] ?: null),($_POST['featured_snack'] ?: null),($_POST['focus_topic'] ?: null),($_POST['presenter_name'] ?: null),($_POST['presenter_topic'] ?: null),($_POST['special_note'] ?: null),$_POST['status']]; if($id){$st=$pdo->prepare('UPDATE meetings SET title=?,slug=?,starts_at=?,ends_at=?,location_name=?,location_details=?,featured_snack=?,focus_topic=?,presenter_name=?,presenter_topic=?,special_note=?,status=? WHERE id=?');$values[]=$id;$st->execute($values);} else {$st=$pdo->prepare('INSERT INTO meetings(title,slug,starts_at,ends_at,location_name,location_details,featured_snack,focus_topic,presenter_name,presenter_topic,special_note,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute($values);} redirect('meetings.php'); } ?>
<h1><?= $id?'Edit':'Create' ?> meeting</h1><form method="post" class="panel"><div class="split"><div><div class="form-row"><label>Title</label><input name="title" required value="<?=h($item['title'])?>"></div><div class="form-row"><label>Slug</label><input name="slug" value="<?=h($item['slug'])?>"></div><div class="form-row"><label>Start date and time</label><input type="datetime-local" name="starts_at" required value="<?=h(format_datetime_local($item['starts_at']))?>"></div><div class="form-row"><label>End date and time</label><input type="datetime-local" name="ends_at" value="<?=h(format_datetime_local($item['ends_at']))?>"></div><div class="form-row"><label>Location name</label><input name="location_name" value="<?=h($item['location_name'])?>"></div><div class="form-row"><label>Location details</label><input name="location_details" value="<?=h($item['location_details'])?>" placeholder="Room, entrance, parking, or special instructions"></div><div class="form-row"><label>Status</label><select name="status"><?php foreach(['draft','scheduled','cancelled'] as $status): ?><option <?=$item['status']===$status?'selected':''?>><?=$status?></option><?php endforeach; ?></select></div></div><div><div class="form-row"><label>Featured snack</label><input name="featured_snack" value="<?=h($item['featured_snack'])?>"></div><div class="form-row"><label>Focus topic or genre</label><input name="focus_topic" value="<?=h($item['focus_topic'])?>" placeholder="Portraiture, mixed media, process feedback, etc."></div><div class="form-row"><label>Presenter name</label><input name="presenter_name" value="<?=h($item['presenter_name'])?>"></div><div class="form-row"><label>Presenter topic</label><input name="presenter_topic" value="<?=h($item['presenter_topic'])?>" placeholder="5 to 10 minute share-out topic"></div><div class="form-row"><label>Special note</label><textarea name="special_note" style="min-height:220px"><?=h($item['special_note'])?></textarea></div></div></div><button class="btn">Save meeting</button></form><?php require __DIR__ . '/_footer.php'; ?>
